<section class="pm-panel"><div class="pm-panel-head"><h2>Department and job position</h2></div><p class="pm-muted">These describe the member's organization. Access roles are approved separately.</p>
<form method="post" action="{{ route('pms.organization.profiles.update', $profile->user_id) }}" class="pm-form-grid">@csrf @method('PUT')
    <label>Department<select name="department_id" data-member-department required><option value="">Choose department</option>@foreach($departments as $department)<option value="{{ $department->id }}" @selected($profile->department_id == $department->id)>{{ $department->name }}</option>@endforeach</select></label>
    <label>Job position<select name="job_position_id" data-member-position required><option value="">Choose job position</option>@foreach($positions as $position)<option value="{{ $position->id }}" data-department="{{ $position->department_id }}" @selected($profile->job_position_id == $position->id)>{{ $position->name }}</option>@endforeach</select></label>
    <button class="pm-button secondary">Save organization details</button>
</form></section>
<script>document.addEventListener('DOMContentLoaded',()=>{const department=document.querySelector('[data-member-department]');const position=document.querySelector('[data-member-position]');if(!department||!position)return;const update=()=>{for(const option of position.options){if(!option.value)continue;option.hidden=option.dataset.department!==department.value;option.disabled=option.hidden;}if(position.selectedOptions[0]?.disabled)position.value='';};department.addEventListener('change',update);update();});</script>
